    if(!response.ok)return;
    const data=await response.json();
    if(data&&typeof data.diagnoses==='object'&&data.diagnoses)GRAMMAR_MISCONCEPTION_BASE=GRAMMAR_MISCONCEPTION_ID=data.diagnoses;
