function vocabSurfaceForm(v){
  const example=String(v?.example||'');if(!example)return null;
  for(const form of vocabWordForms(v?.word)){
    const m=example.match(new RegExp(`(^|[^A-Za-z])(${rxEsc(form)})([^A-Za-z]|$)`,'i'));
    if(m)return m[2];
  }
  return null;
}
