function reminderInviteOffers(){return Number(readReminderInvite().offers||0)}
// Undangan hanya layak muncul kalau browser bisa menjawabnya, murid belum memutuskan apa
// pun, dan jatah tawaran belum habis. 'denied' TIDAK ditawari lagi: browser tidak akan
// menampilkan dialognya untuk kedua kali, jadi mengulang tawaran hanya akan menghasilkan
// panel yang tidak bisa berbuat apa-apa. Jalan masuknya kembali ada di Pengaturan.
function shouldInviteNotifications(){
  if(!notificationsSupported())return false;
  if(notificationPermission()!=='default')return false;
  if(state.preferences?.reminders===false)return false;
  return reminderInviteOffers()<REMINDER_INVITE_MAX_OFFERS;
}
function setNotificationGateState(status){
  const gate=$('welcome'),button=$('notificationGateButton'),body=$('notificationGateBody'),stateText=$('notificationGateStatus'),help=$('notificationGateHelp'),title=$('welcomeTitle'),skip=$('notificationGateSkip');if(!gate)return;
  // m025-80 OWNER: "walaupun notifikasi dan puter sudah diaktifkan, setiap kali masuk apps
  // selalu muncul popup cepat". Panel yang sedang tersembunyi dan sudah dijawab tidak perlu
  // dibuka sama sekali hanya untuk ditutup lagi 220ms kemudian.
  const wasHidden=gate.classList.contains('hidden');
  if(!(wasHidden&&(status==='granted'||status==='declined'))){
    gate.classList.remove('hidden');(window.requestAnimationFrame||setTimeout)(()=>gate.classList.add('show'));
    /* Audit UI/UX 2026-08-30 (D9): dialog wajib mengurung fokus. Terukur sebelum ini:
       22 dari 26 perhentian Tab mendarat DI LUAR gerbang, pada kontrol yang tertutup
       scrim .82 dan tidak bisa diklik. Resepnya kini sama untuk semua lapisan. */
    if(wasHidden){gateReturnFocus=document.activeElement;
      (window.requestAnimationFrame||setTimeout)(()=>{try{syncDialogContainment();$('notificationGateButton')?.focus?.({preventScroll:true})}catch(_){}})}
    else try{syncDialogContainment()}catch(_){}
  }
  if(title)title.textContent=FiezelI18n.t('notif.gate-title');
  if(skip)skip.textContent=FiezelI18n.t('notif.skip-link');
  const badge=gate.querySelector('.welcome-mark');if(badge)badge.textContent=FiezelI18n.t('notif.gate-badge');
  const req=gate.querySelector('.notification-requirement span');if(req)req.textContent=FiezelI18n.t('notif.gate-terms');
  // Naskah di bawah ini adalah inti pembalikan m025-34. Tidak ada lagi "terkunci", "syarat
  // masuk", atau "belum bisa dibuka": setiap cabang - termasuk ditolak dan tidak didukung -
  // berakhir dengan murid tetap bisa belajar.
  if(status==='granted'){
    stateText.textContent=FiezelI18n.t('notif.status-aktif');stateText.className='notification-status success';button.disabled=true;button.innerHTML=`<i data-lucide="circle-check-big"></i> ${FiezelI18n.t('notif.tombol-aktif')}`;help.textContent=FiezelI18n.t('notif.bantuan-aktif');
  }else if(status==='denied'){
    stateText.textContent=FiezelI18n.t('notif.status-ditolak');stateText.className='notification-status';button.disabled=true;button.innerHTML=`<i data-lucide="bell"></i> ${FiezelI18n.t('notif.tombol-nonaktif')}`;body.textContent=FiezelI18n.t('notif.badan-ditolak');help.innerHTML=FiezelI18n.t('notif.bantuan-ditolak');
  }else if(status==='unsupported'){
    stateText.textContent=FiezelI18n.t('notif.status-unsupported');stateText.className='notification-status';button.disabled=true;button.textContent=FiezelI18n.t('notif.tombol-unsupported');body.textContent=FiezelI18n.t('notif.badan-unsupported');help.textContent=FiezelI18n.t('notif.bantuan-unsupported');
  }else if(status==='declined'){
    stateText.textContent=FiezelI18n.t('notif.status-nanti');stateText.className='notification-status';button.disabled=true;button.innerHTML=`<i data-lucide="bell"></i> ${FiezelI18n.t('notif.tombol-nanti')}`;help.textContent=FiezelI18n.t('notif.bantuan-nanti');
  }else{
    stateText.textContent=FiezelI18n.t('notif.status-default');stateText.className='notification-status';button.disabled=false;button.innerHTML=`${FiezelI18n.t('notif.tombol-ingatkan')} <i data-lucide="bell-ring"></i>`;body.textContent=FiezelI18n.t('notif.gate-desc');help.textContent=FiezelI18n.t('notif.help-init');
  }
  refreshIcons();
}
let gateReturnFocus=null;
/* Fokus dikembalikan ke pemicu supaya pengguna keyboard tidak terdampar di <body> -
   pola yang sama dengan closeModalNow(). syncDialogContainment() dipanggil SETELAH
   kelas .hidden terpasang, karena ia membaca kelas itu untuk tahu apa yang masih terbuka. */
function releaseGateFocus(){
  try{syncDialogContainment()}catch(_){}
  try{if(gateReturnFocus&&document.contains(gateReturnFocus)&&!gateReturnFocus.inert)gateReturnFocus.focus({preventScroll:true})}catch(_){}
  gateReturnFocus=null;
  /* SISI KEDUA dari penjaga di maybeShowDailyRitual(). Penjaga itu menolak menerbitkan
     ritual di belakang gerbang dan sengaja keluar SEBELUM menandai ritualMeta, supaya
     jatah "sekali sehari" tidak hangus. Tapi menahan saja tidak cukup: tanpa tawaran
     ulang di sini, murid yang boot-nya melewati gerbang tidak akan melihat rencana
     harinya SAMA SEKALI - lebih buruk daripada cacat aslinya, yang setidaknya masih
     menampilkannya begitu gerbang turun. Diukur berdampingan dengan main saat menulis
     ini: main "ritual kembali 0ms", cabang ini "TIDAK PERNAH" sebelum baris ini ada.
     maybeShowDailyRitual() menjaga syaratnya sendiri (view home, belum ada kartu, tidak
     ada dialog lain, jatah hari ini belum terpakai), jadi pemanggilan ini idempoten dan
     aman dipanggil dari kedua gerbang. */
  setTimeout(()=>{try{maybeShowDailyRitual()}catch(_){}},360);
}
function hideNotificationGate(){const gate=$('welcome');if(!gate)return;gate.classList.remove('show');setTimeout(()=>{gate.classList.add('hidden');releaseGateFocus()},300)}
// m025-79: a second mandatory gate, Puter account sign-in, sits right after the
// notification gate clears. It reuses the same lock/overlay pattern (a body class that
// hides .app/.bottomnav, plus a full-screen panel) and aiErrorMessage() for failure copy,
// so sign-in errors read the same way AI errors already do elsewhere in the app.
// SDK Puter dimuat async (lihat ./fiezel-puter-ready.js). Dua pemeriksaan di bawah ini
// tetap sinkron dan tetap menjawab "sekarang" - itu yang dibutuhkan jalur render. Yang
// TIDAK boleh dilakukan lagi adalah menyimpulkan "Puter tidak tersedia" dari jawaban
// "belum ada sekarang": setiap jalur yang bisa menunggu, menunggu lewat awaitPuter().
function puterAuthAvailable(){return typeof puter!=='undefined'&&!!puter?.auth}
function puterSignedIn(){try{return puterAuthAvailable()&&puter.auth.isSignedIn?.()===true}catch{return false}}
// Menunggu SDK-nya tiba. Mengembalikan objek puter atau null kalau ia memang tidak akan
// datang (offline, diblokir, layanan mati) - jadi pemanggil punya jawaban yang pasti,
// bukan penantian tanpa ujung.
async function awaitPuter(timeoutMs){
  if(typeof puter!=='undefined'&&puter)return puter;
  try{const sdk=await self.FiezelPuterReady?.ready?.(timeoutMs);if(sdk)return sdk}catch{}
  return typeof puter!=='undefined'&&puter?puter:null
}
function setAuthGateState(status,detail){
  const gate=$('authGate'),button=$('authGateButton'),stateText=$('authGateStatus'),skip=$('authGateSkip');if(!gate)return;
  // Sama seperti gerbang notifikasi: akun yang sudah tersambung tidak boleh memunculkan
  // panel hanya untuk ditutup lagi sesaat kemudian (m025-80).
  const wasHidden=gate.classList.contains('hidden');
  if(!(wasHidden&&status==='signed_in')){
    gate.classList.remove('hidden');(window.requestAnimationFrame||setTimeout)(()=>gate.classList.add('show'));
    if(wasHidden){gateReturnFocus=document.activeElement;
      (window.requestAnimationFrame||setTimeout)(()=>{try{syncDialogContainment();$('authGateButton')?.focus?.({preventScroll:true})}catch(_){}})}
    else try{syncDialogContainment()}catch(_){}
  }
  if($('authGateTitle'))$('authGateTitle').textContent=FiezelI18n.t('auth.gate-title');
  if($('authGateBody'))$('authGateBody').textContent=FiezelI18n.t('auth.gate-body');
  if(skip)skip.textContent=FiezelI18n.t('auth.skip-btn');
  if($('authGateSkipHelp'))$('authGateSkipHelp').textContent=FiezelI18n.t('auth.skip-help');
  if($('authGateHelp'))$('authGateHelp').textContent=FiezelI18n.t('auth.puter-help');
  const legal=gate.querySelector('.auth-legal');if(legal)legal.textContent=FiezelI18n.t('auth.legal-note');
  // Audit UX Bagian 3: status login adalah komponen sendiri (.auth-status), bukan alert
  // bawaan browser, dan naskahnya tidak menyapa nama murid.
  if(status==='signed_in'){stateText.textContent=FiezelI18n.t('auth.status-tersambung');stateText.className='auth-status success';button.disabled=true;button.innerHTML=`<i data-lucide="circle-check-big"></i><span>${FiezelI18n.t('auth.tombol-tersambung')}</span>`}
  else if(status==='pending'){stateText.textContent=FiezelI18n.t('auth.status-menghubungkan');stateText.className='auth-status';button.disabled=true;button.innerHTML=`<i data-lucide="loader-circle"></i><span>${FiezelI18n.t('auth.tombol-menghubungkan')}</span>`}
  else if(status==='error'){stateText.textContent=aiErrorMessage(detail);stateText.className='auth-status error';button.disabled=false;button.innerHTML=`<i data-lucide="refresh-cw"></i><span>${FiezelI18n.t('auth.tombol-retry')}</span>`}
  // "Lanjut tanpa akun" ditekan: nadanya sama dengan 'declined' di gerbang notifikasi -
  // tidak ada yang gagal, tidak ada yang tertahan.
  else if(status==='skipped'){stateText.textContent=FiezelI18n.t('auth.status-dilewati');stateText.className='auth-status';button.disabled=true;if(skip)skip.disabled=true}
  else{stateText.textContent=FiezelI18n.t('auth.status-idle');stateText.className='auth-status';button.disabled=false;button.innerHTML=`<i data-lucide="user-round"></i><span>${FiezelI18n.t('auth.tombol-lanjutkan')}</span>`;if(skip)skip.disabled=false}
  refreshIcons()
}
function hideAuthGate(){const gate=$('authGate');if(!gate)return;gate.classList.remove('show');setTimeout(()=>{gate.classList.add('hidden');releaseGateFocus()},300)}
async function completeAuthGate(){await activateAccountStateFromPuter();document.body?.classList?.remove?.('auth-locked');setAuthGateState('signed_in');setTimeout(hideAuthGate,220);showToast(FiezelI18n.t('auth.toast-tersambung'));armOfflineVoiceAutoload();runPendingAfterGateFn()}
function runPendingAfterGateFn(){if(!pendingAfterGateFn)return;const fn=pendingAfterGateFn;pendingAfterGateFn=null;setTimeout(fn,240)/* v06: tunggu gerbang benar-benar turun sebelum kuis mendorong stage */}
// m026-02 AKAR: gerbang akun dipasang di SETIAP boot tanpa memori apa pun, dan satu-satunya
// tombolnya adalah "Lanjutkan dengan Puter" - jadi murid yang tidak mau (atau belum bisa)
// login terkurung di balik .auth-locked (style.css:438). Dua obatnya di bawah ini:
//
//   1. PENANDA LEWAT. Murid yang memilih "Lanjut tanpa akun" tidak ditanya lagi di boot
//      berikutnya. Penandanya di localStorage, BUKAN di state progres, karena ini bukan
//      bukti belajar - pola yang sama dengan REMINDER_INVITE_KEY di atas.
//   2. SATU KALI PER PERIODE, DI LUAR SESI. Keputusannya dipisah menjadi fungsi murni
//      shouldPresentPuterPopup() supaya bisa diuji tanpa DOM, tanpa jam nyata, dan tanpa
//      localStorage: seluruh masukannya parameter.
const PUTER_POPUP_PERIOD_MS=86400000;
const PUTER_POPUP_LAST_KEY='fiezel-puter-popup-last';
const PUTER_AUTH_SKIP_KEY='fiezel-puter-auth-skipped';
/**
 * Satu-satunya tempat "boleh muncul atau tidak" diputuskan. Murni: tidak memanggil
 * Date.now(), tidak menyentuh localStorage, tidak melihat DOM.
 *
 * @param {{now:number,lastShownAt:*,signedIn:boolean,listeningActive:boolean}} ctx
 * @returns {boolean}
 */
function shouldPresentPuterPopup(ctx){
  const c=ctx||{};
  // Akun sudah tersambung: tidak ada yang perlu ditawarkan.
  if(c.signedIn===true)return false;
  // Sesi dengar sedang jalan. Jalur tolak ini TIDAK menulis timestamp apa pun, jadi
  // penekanan di tengah sesi tidak memakan jatah periode - popupnya cuma menunggu.
  if(c.listeningActive===true)return false;
  const now=Number(c.now);
  if(!Number.isFinite(now))return false;
  const last=Number(c.lastShownAt);
  // lastShownAt korup ('abc', -5, undefined) diperlakukan seperti "belum pernah" - lebih
  // baik satu popup yang sah daripada melempar di tengah boot.
  if(!Number.isFinite(last)||last<=0)return true;
  return now-last>=PUTER_POPUP_PERIOD_MS;
}
/** Menulis waktu tampil lewat store yang di-inject (localStorage di runtime, Map palsu di test). */
function markPuterPopupShown(now,store){
  const target=store||(typeof localStorage!=='undefined'?localStorage:null);
  const stamp=Number(now);
  if(!target||typeof target.setItem!=='function')return false;
  if(!Number.isFinite(stamp)||stamp<=0)return false;
  try{target.setItem(PUTER_POPUP_LAST_KEY,String(Math.floor(stamp)))}catch{}
  return true;
}
function readPuterPopupLastShown(store){
  const target=store||(typeof localStorage!=='undefined'?localStorage:null);
  if(!target||typeof target.getItem!=='function')return null;
  try{return target.getItem(PUTER_POPUP_LAST_KEY)}catch{return null}
}
function puterAuthSkipped(){
  try{if(localStorage.getItem(PUTER_AUTH_SKIP_KEY)==='1')return true}catch{}
  return state?.preferences?.puterAuthSkipped===true;
}
// Sesi dengar aktif = ada controller Skills Lab hidup, atau layar yang sedang dibuka
// memang salah satu panggung dengar/bicara (daftar view di renderInner()).
function puterListeningActive(){
  try{
    if(typeof speakingListeningController!=='undefined'&&speakingListeningController)return true;
    return ['skills','listening','speaking'].includes(String(state?.view||''));
  }catch{return false}
}
/**
 * "Lanjut tanpa akun". Cermin declineStudyNotifications(): jawaban yang sah, bukan
 * kegagalan. Kuncinya dilepas, penandanya ditulis, dan Pengaturan -> Akun Puter tetap
 * menjadi jalan masuknya kembali (lihat accountSettingsMarkup()).
 */
function skipPuterSignIn(){
  try{localStorage.setItem(PUTER_AUTH_SKIP_KEY,'1')}catch{}
  try{state.preferences={...state.preferences,puterAuthSkipped:true};save()}catch{}
  haptic('tap');
  document.body?.classList?.remove?.('auth-locked');
  setAuthGateState('skipped');
  runPendingAfterGateFn();/* v06: kuis yang tertunda di balik gerbang ikut jalan di jalur 'Lanjut tanpa akun' */
  setTimeout(hideAuthGate,220);
  showToast(FiezelI18n.t('auth.toast-lewati'));
  return true
}
let authRetryBound=false;
function presentPuterAuthGateIfNeeded(){
  if(!puterAuthAvailable())return false;
  if(puterSignedIn()){activateAccountStateFromPuter();return false}
  // Murid sudah pernah memilih jalan tanpa akun. Menanyakannya lagi setiap boot adalah
  // dark-pattern yang sama dengan gerbang notifikasi lama.
  if(puterAuthSkipped())return false;
  /* q19-P1 2026-08-29: ujian/lesson aktif diperlakukan persis seperti sesi dengar \u2014 gerbang
     menunggu, timestamp tidak ditulis, jatah periode tidak terbakar. Sebelumnya gerbang
     \u201cMasuk ke FIEZEL\u201d bisa mendarat DI ATAS placement yang sedang berjalan. */
  const listeningActive=puterListeningActive()||!!(self.FiezelStage?.lessonMode?.()&&state.activeSession);
  const at=Date.now();
  if(!shouldPresentPuterPopup({now:at,lastShownAt:readPuterPopupLastShown(),signedIn:puterSignedIn(),listeningActive}))return false;
  markPuterPopupShown(at);
  document.body?.classList?.add?.('auth-locked');setAuthGateState('idle');
  if(!authRetryBound){authRetryBound=true;document.addEventListener?.('visibilitychange',()=>{if(document.visibilityState==='visible'&&document.body?.classList?.contains('auth-locked')&&puterSignedIn())completeAuthGate()})}
  armOfflineAuthGateEscape();
  return true
}
/* m025-246 — GERBANG AKUN TIDAK BOLEH MENGURUNG MURID YANG SEDANG OFFLINE.
   OWNER (edge case wajib): "Offline saat gerbang akun: timeout <=3 detik ke 'Lanjut
   tanpa akun' otomatis."

   Gerbang ini memasang `.auth-locked` di <body>, dan kelas itu benar-benar mengunci
   layar (style.css:438). Satu-satunya tombol yang membukanya - "Lanjutkan dengan
   Puter" - butuh jaringan. Murid yang membuka FIEZEL di angkot tanpa sinyal karena
   itu menatap gerbang yang tidak punya jalan keluar sampai sinyalnya kembali.

   TIGA DETIK, dan bukan lebih: itu batas yang diminta owner, dan ia juga batas yang
   masuk akal - login Puter yang sehat menyelesaikan handshake jauh di bawah itu.

   YANG DILAKUKANNYA sengaja BUKAN sekadar menyembunyikan gerbang: ia memanggil
   skipPuterSignIn(), jalur "Lanjut tanpa akun" yang sudah ada. Jadi kunci dilepas,
   kuis yang tertunda ikut jalan (runPendingAfterGateFn), dan penandanya tercatat -
   satu perilaku, bukan dua yang harus terus disepakatkan.

   TIDAK menutup gerbang yang sedang bekerja: kalau murid sudah menekan tombol
   (status 'pending') atau sudah masuk, jam ini mundur dan tidak melakukan apa pun. */
const OFFLINE_AUTH_ESCAPE_MS=3000;
let offlineAuthEscapeTimer=null;
function offlineNow(){try{return typeof navigator!=='undefined'&&navigator.onLine===false}catch(_){return false}}
function armOfflineAuthGateEscape(){
  if(!offlineNow())return false;
  if(offlineAuthEscapeTimer)return false;
  if(typeof setTimeout!=='function')return false;
  const note=$('authGateStatus');
  if(note){try{note.textContent=FiezelI18n.t('account.offline-catatan')}catch(_){}}
  offlineAuthEscapeTimer=setTimeout(()=>{
    offlineAuthEscapeTimer=null;
    try{
      if(!document.body?.classList?.contains?.('auth-locked'))return;
      if(puterSignedIn())return;
      skipPuterSignIn();
    }catch(_){}
  },OFFLINE_AUTH_ESCAPE_MS);
  offlineAuthEscapeTimer?.unref?.();
  return true;
}
/**
 * m026-02 pemberitahuan kredit habis - MILIK FIEZEL, bukan dialog SDK.
 *
 * Dipanggil hanya di ujung sesi (onSessionEnd addon listening: renderComplete()/exit()),
 * jadi ia tidak pernah memotong item yang sedang diputar. listeningActive:false ditulis
 * eksplisit karena titik panggilnya ADALAH momen "sesi sudah selesai" - controllernya
 * mungkin masih terpasang sedetik lagi. signedIn:false juga eksplisit: aturan "sudah
 * login berarti diam" milik gerbang LOGIN, sedangkan pemberitahuan ini justru hanya lahir
 * pada akun yang sudah login dan kreditnya habis.
 */
function maybePresentPuterCreditNotice(){
  let pending=false;
  try{pending=self.FiezelPuterVoice?.consumeCreditNotice?.()===true}catch{}
  if(!pending)return false;
  const at=Date.now();
  if(!shouldPresentPuterPopup({now:at,lastShownAt:readPuterPopupLastShown(),signedIn:false,listeningActive:false}))return false;
  markPuterPopupShown(at);
  /* A8 naskah + aksesibilitas. Tiga hal yang DIPERBAIKI di sini, semuanya pelanggaran kanon:
     (1) judul lamanya menyebut nama layanan mesin ("Kredit AI Puter kamu habis") - murid
         nggak pernah membaca nama mesin, dan nama itu juga bukan sesuatu yang bisa dia
         perbaiki;
     (2) di dalamnya ada TAUTAN `<a>` ke halaman pemakaian berbayar ("Pelajari opsi
         upgrade") - itu permukaan bayar di panel jatah, dan `paymentEnabled=false`
         ditegakkan sebagai KETIADAAN elemen, bukan tombol nonaktif;
     (3) kalimatnya memakai "tidak" alih-alih "nggak".
     Naskahnya sekarang milik features/quota/quota-copy.js, jadi satu perubahan kalimat
     berlaku di semua permukaan sekaligus. */
  return presentQuotaNotice({copyKey:'quota.ai.exhausted',spoken:true})
}
/**
 * A8 · satu-satunya jalan menampilkan pemberitahuan jatah/suara ke murid.
 *
 * MENGAPA BUKAN showToast(): toast di app.js:2521 menghilang sendiri sesudah 2.600 ms. Itu
 * cukup untuk "Terkirim, terima kasih!" dan NGGAK cukup untuk kalimat yang menjelaskan apa
 * yang rusak, apa yang tetap jalan, dan apa yang harus dilakukan. Pemberitahuan ini menetap
 * sampai murid menutupnya sendiri.
 *
 * ATURAN SENYAP SESI DENGAR: kalau sesi listening sedang berjalan, pemberitahuan ini nggak
 * ditampilkan sama sekali - ia menunggu `onSessionEnd`. Wilayah `aria-live` yang berbicara di
 * tengah kalimat soal listening merusak ujiannya (alasan lengkap di quota-copy.js §3).
 *
 * Fokus TIDAK dirampas: nggak ada `.focus()` di sini, jadi murid yang sedang mengisi jawaban
 * tetap di kolomnya.
 */
function presentQuotaNotice(facts){
  const copy=self.FiezelQuotaCopy;
  const listeningActive=(()=>{try{return puterListeningActive()===true}catch{return false}})();
  if(listeningActive)return false;
  if(!copy?.build||!copy?.panelMarkup){
    // Naskah cadangan kalau modulnya belum termuat. Ia tetap jujur dan tetap kanon, cuma
    // lebih pendek - yang dilarang adalah kebisuan, bukan kalimat yang sederhana.
    openModal(`<div class="modal-mark">FIEZEL</div><section class="fz-notice fz-notice-advisory" role="status" aria-live="polite" aria-atomic="true"><h2 class="fz-notice-title">${FiezelI18n.t('quota.fallback-judul')}</h2><p class="fz-notice-body">${FiezelI18n.t('quota.fallback-badan')}</p><div class="fz-notice-actions"><button type="button" class="fz-notice-btn" id="quotaNoticeClose">${FiezelI18n.t('quota.fallback-tombol')}</button></div></section>`);
    $('quotaNoticeClose')?.addEventListener('click',closeModal);
    return true
  }
  const notice=copy.build(Object.assign({online:typeof navigator==='undefined'||navigator?.onLine!==false,listeningActive:false},facts||{}));
  openModal(`<div class="modal-mark">FIEZEL</div>${copy.panelMarkup(notice)}`);
  $('modalPanel')?.querySelector?.('[data-fz-notice-dismiss]')?.addEventListener('click',closeModal);
  return true
}
// Tenggat login. Keadaan 'pending' mematikan tombolnya, dan tidak ada apa pun yang
// menyalakannya kembali kalau puter.auth.signIn() tidak pernah selesai - jendela login
// diblokir peramban, atau SDK-nya menggantung setelah terhubung. Yang tersisa adalah gerbang
// penuh layar bertuliskan "Menghubungkan..." dengan satu-satunya tombolnya mati, dan satu-
// satunya jalan keluar memuat ulang halaman. Sebuah janji yang tidak pernah selesai bukan
// alasan untuk mengurung murid.
const PUTER_SIGNIN_TIMEOUT_MS=45000;
async function attemptPuterSignIn(){
  // Ini gestur murid yang sesungguhnya, jadi ia tidak boleh gagal diam-diam hanya karena
  // js.puter.com kebetulan belum tiba. Panelnya berpindah ke 'pending' DULU, lalu SDK-nya
  // ditunggu; kalau ternyata memang tidak datang, kegagalannya dinamai, bukan disembunyikan.
  if(!puterAuthAvailable()){
    setAuthGateState('pending');
    await awaitPuter();
    if(!puterAuthAvailable()){setAuthGateState('error',{message:FiezelI18n.t('auth.galat-layanan')});return false}
  }
  setAuthGateState('pending');
  try{
    await Promise.race([
      puter.auth.signIn(),
      new Promise((_,reject)=>setTimeout(()=>reject(new Error(FiezelI18n.t('auth.galat-timeout'))),PUTER_SIGNIN_TIMEOUT_MS))
    ]);
    if(puterSignedIn()){await completeAuthGate();return true}
    setAuthGateState('error',{message:FiezelI18n.t('auth.galat-unfinished')});return false
  }
  // Tenggat ditangkap di sini juga, bukan dibiarkan lewat: hasilnya harus sama seperti
  // kegagalan login lain - tombolnya hidup kembali dan bisa ditekan.
  catch(error){if(puterSignedIn()){await completeAuthGate();return true}setAuthGateState('error',error);return false}
}
