// sapaan satu kalimat dari gelembung, bukan paragraf laporan.
function coachBubbleContext(){
  const snapshot=buildLearningSnapshot(),journey=buildPersonalJourney();
  const focus=journey?.mission?.focusSkill?String(journey.mission.focusSkill).replace(/_/g,' '):(journey?.mission?.focusDomain||'');
  return{view:state.view,level:snapshot.activeLevel||getActiveLevel(),streak:Number(state.streak)||0,dueReviews:Number(snapshot.dueReviews)||0,todayAttempts:Number(state.daily?.attempts)||0,focusLabel:focus};
}
function coachAskPrompt(question,ctx){
  const c=ctx||{};
  /* W3-BRAIN-TH: cabang th (DRAFT AI) sebelum return id yang byte-identik. Konteks angka
   * (level, streak, review) diteruskan sama persis; gradeLabel/semester masih data id dari
   * LEARNER_STAGE - keterbatasan bank data, dicatat di laporan W3-BRAIN-TH. */
  if(FiezelI18n.getLocale()==='th')return `\u0E04\u0E38\u0E13คือ FIEZEL โค้ชการเรียนภาษาอังกฤษของนักเรียนมัธยมปลายหนึ่งคนชื่อ ${learnerName()}
สไตล์: เป็นกันเอง อบอุ่น เหมือนรุ่นพี่ที่นั่งติวอยู่ข้าง ๆ ใช้อีโมจิได้เท่าที่จำเป็น
กฎเหล็ก: ตอบไม่เกิน 60 คำ ไม่เกิน 3 ประโยค ห้ามทำรายการแบบมีหมายเลข ห้ามใส่หัวข้อ นี่คือบทสนทนา ไม่ใช่รายงาน
ถ้าเข้าเรื่อง ให้ปิดท้ายด้วยคำชวนเล็ก ๆ ที่ลงมือทำได้ทันที
ข้อมูลนักเรียน: ${LEARNER_STAGE.gradeLabel} \u0E40\u0E17\u0E2D\u0E21 ${LEARNER_STAGE.semester}, ระดับ ${c.level||'A1'}, สตรีค ${c.streak||0} วัน, มี ${c.dueReviews||0} บทรอรีวิว, กำลังเปิดหน้า "${c.view||'home'}", โฟกัสสัปดาห์นี้ ${c.focusLabel||'ยังไม่กำหนด'}
คำถามของนักเรียน: "${String(question||'').slice(0,600)}"`;
  return `Kamu FIEZEL, pembimbing belajar Bahasa Inggris untuk satu murid SMA Indonesia bernama ${learnerName()}.
Gaya: santai, gaul, akrab seperti kakak yang nemenin belajar. Boleh emoji seperlunya.
ATURAN KETAT: jawab maksimal 60 kata, maksimal 3 kalimat, tanpa daftar bernomor, tanpa judul. Ini percakapan, bukan laporan.
Kalau relevan, akhiri dengan satu ajakan kecil yang bisa dikerjakan sekarang.
Konteks murid: ${LEARNER_STAGE.gradeLabel} semester ${LEARNER_STAGE.semester}, level ${c.level||'A1'}, runtun ${c.streak||0} hari, ${c.dueReviews||0} materi menunggu review, sedang membuka halaman "${c.view||'home'}", fokus minggu ini ${c.focusLabel||'belum ditentukan'}.
Pertanyaan murid: "${String(question||'').slice(0,600)}"`;
}
function syncCoachBubble(){
  try{
    /* m025-266: openAsk adalah SATU-SATUNYA pintu ke layar Tanya FIEZEL (askView) sejak
       m025-254 mengganti tombol topbar-nya dengan lonceng. Komentar index.html menjanjikan
       "aksesnya lewat pembimbing PAW", tapi tidak ada kode yang menepatinya - layar itu
       yatim sebelas build. Nama view ditulis DI SINI, bukan di modul gelembung, supaya
       tests/view-reachability-test.js menemukannya sebagai go('ask') dan modul gelembung
       tetap tidak tahu nama rute apa pun. */
    const api=self.FiezelCoachBubble?.install?.({ask:(question,ctx)=>askFiezelAI(coachAskPrompt(question,ctx),'coach_question',{question,level:getActiveLevel(),lessonId:String(ctx?.lessonId||ctx?.view||''),focusLabel:String(ctx?.focusLabel||ctx?.title||'')}),openAsk:()=>go('ask')});
    api?.update?.(coachBubbleContext());
  }catch(_){}
}
// m025-115: tiga tujuan baru untuk tiga skill inti tes yang belum punya halamannya
// sendiri. Tidak ada tujuan lama yang dihapus - brief bagian 2 menyebutnya sebagai
// batasan pertama: "Nol fitur dihapus."
/* m025-246: 'latihan' ditambahkan, TIDAK ADA yang dibuang. Tab bar sekarang hanya
   menampilkan empat dari daftar ini, tetapi rute lama tetap sah - back-nav murid lama,
   tautan dalam layar, dan tur semuanya membawa nama view yang sudah ada, dan menghapus
   satu nama dari himpunan ini akan membuat go() menampilkan toast "halaman tak tersedia"
   pada perjalanan yang benar-benar valid. */
const VALID_VIEWS=new Set(['home','latihan','vocab','grammar','reading','skills','listening','speaking','writing','test','progress','classroom','library','ask','search','online','profile','learn','tutor']);
function prefersReducedMotion(){try{return !!(self.matchMedia&&self.matchMedia('(prefers-reduced-motion: reduce)').matches)}catch(_){return false}}
// m026-01 - maskot PAW. Tiga pembungkus di bawah ini adalah SATU-SATUNYA cara app.js
// berbicara dengan <fiezel-mascot>. Alasannya:
//
// 1. Titik pasangnya ada di jalur panas: answerFeedbackSignal (tiap jawaban),
//    finishQuiz (tiap sesi tuntas), callback perkenalan. Reaksi gerak adalah lapisan
//    paling boleh gagal di aplikasi ini, jadi ia tidak pernah boleh melempar ke atas.
// 2. Hormat pada pengaturan gerak. Murid yang mematikan animasi, atau sistem yang
//    minta prefers-reduced-motion, tidak mendapat reaksi maskot sama sekali - bukan
//    versi lebih pelan. Ini pemeriksaan yang sama yang dipakai celebrate().
// 3. Kalau motion system-nya tidak ada (cache lama, berkas gagal dimuat), semuanya
//    diam tanpa suara. Tidak ada cabang darurat, tidak ada log yang menakuti murid.
function pawMotionAllowed(){if(prefersReducedMotion())return false;return state.preferences?.motion!==false}
/* [OUTFIT G5'] Lapisan outfit kontekstual (features/mascot/fiezel-paw-outfit.js)
   diberi tahu SEBELUM gerbang gerak: outfit adalah geometri statis yang tetap sah
   tampil saat kurangi-gerak (19 §6.4). Optional-chaining: tanpa berkasnya, senyap. */
function pawReact(evt,detail){try{self.FiezelPawOutfit?.context?.(evt,{motion:pawMotionAllowed()})}catch(_){}if(!pawMotionAllowed())return false;try{return !!self.FiezelPaw?.react?.(evt,detail)}catch(_){return false}}
function pawSetState(name,opts){if(!pawMotionAllowed())return false;try{return !!self.FiezelPaw?.setState?.(name,opts)}catch(_){return false}}
/* 2026-08-29 overhaul I14 (O3 §9): dua pintu kanonis TAMBAHAN untuk maskot ber-INSTANCE.
   pawReact/pawSetState menyiarkan ke SEMUA instance hidup — untuk momen yang miliknya SATU
   layar (wajah layar hasil, node jalur, kartu ajar-ulang), siaran berarti perayaan ganda di
   gelembung pembimbing. Sebelum ini layar hasil meng-querySelector instance-nya sendiri —
   pola itu diresmikan di sini supaya app.js tidak pernah lagi mengutak-atik DOM maskot ad-hoc:
   - pawStageState(sel,name,opts,staticFace): state pada instance terpilih, gerbang gerak yang
     SAMA dengan pawSetState; jalur kurangi-gerak jatuh ke bingkai statis applyFace (aman
     pasca perbaikan rig I8) bila staticFace diberikan — nol animasi, informasi tetap ada.
   - pawStagePose(sel,pose): pose statis dari pustaka 16 pose (geometri diam, bukan gerak —
     preseden slot .is-static), sah pada kurangi-gerak; tidak pernah melempar. */
function pawStageState(sel,name,opts,staticFace){let el=null;try{el=document.querySelector(sel)}catch(_){}if(!el)return false;try{
  if(pawMotionAllowed()&&typeof el.setState==='function')return !!el.setState(name,opts);
  if(staticFace&&typeof el.applyFace==='function')return !!el.applyFace(staticFace);
}catch(_){}return false}
function pawStagePose(sel,pose){try{const el=document.querySelector(sel);return !!(el&&typeof el.applyPose==='function'&&el.applyPose(pose))}catch(_){return false}}
/* [FASE-4] 09 §2.15: milestone SEKALI SEUMUR HIDUP per kunci — gerbangnya di storage
   app (state.pawMilestones), bukan di memori komponen yang hangus tiap muat ulang.
   Kunci resmi: placement-complete, streak-7/30/100, level-c2. Daftar blok 13 §4.4
   (streak jawaban, gem, sesi selesai, lencana) TIDAK pernah lewat sini. */
function pawMilestone(key){
  const k=String(key||'');if(!k)return false;
  const done=Array.isArray(state.pawMilestones)?state.pawMilestones:[];
  if(done.includes(k))return false;
  state.pawMilestones=done.concat(k);save();
  const reacted=pawReact('milestone',{key:k});
  // [ADAPTASI] OA-7 §4 baris MILESTONE: kunci selain streak-* dan placement-complete
  // (level-c2 dan penerus once-ever lain) dibunyikan level_up di sini. streak-7/30/100
  // sudah dibunyikan streak_10 oleh pawStreakWatch dan placement-complete dibunyikan
  // exam_complete di finishQuiz — satu momen satu bunyi, tidak menumpuk lapisan.
  if(reacted&&!k.startsWith('streak-')&&k!=='placement-complete')uiSfx('level_up');
  return reacted
}
/* [FASE-4] 09 §3.3: pisah 'wake' vs 'welcome-back'. Stempel kunjungan terakhir
   DIPERSISTEN (state.pawLastSeenAt); kembali setelah ≥4 jam atau hari kalender baru
   → welcome-back (otomatis maks 1×/4 jam karena stempelnya ikut maju). Sisanya wake. */
function pawGreetReturn(now=Date.now()){
  const last=Number(state.pawLastSeenAt)||0;
  state.pawLastSeenAt=now;save();
  if(last&&(now-last>=4*3600*1000||studyDayKey(now)!==studyDayKey(last))){
    // [ADAPTASI] OA-7 §4 baris SAPAAN: welcome-back = slot sapaan → paw_greet (bunyi
    // tanda tangan). Berbunyi HANYA bila reaksinya benar-benar menyala — saat gerak
    // ditekan, sapaan tanpa maskot yang menyapa adalah bunyi yatim (14 §3.1 aturan 3).
    // 'wake' tetap senyap: bangun dari layar yang sama bukan momen sapaan.
    if(pawReact('welcome-back'))uiSfx('paw_greet');
    return 'welcome-back'
  }
  pawReact('wake');return 'wake'
}
/* [FASE-4] 09 §3.3 idle-timeout: 90 detik tanpa sentuhan DI LAYAR SANTAI (home,
   progress) → maskot mengantuk; sentuhan pertama sesudahnya → 'wake'. Tidak pernah
   berjalan di tengah soal/dengar/bicara — daftar view-nya yang menjaga itu. */
let pawIdleT=null,pawAsleep=false,pawIdleArmedAt=0;
const PAW_AMBIENT_VIEWS=new Set(['home','progress']);
function pawIdleArm(){
  clearTimeout(pawIdleT);pawIdleT=null;
  if(!PAW_AMBIENT_VIEWS.has(state.view))return;
  pawIdleT=setTimeout(()=>{pawIdleT=null;
    if(PAW_AMBIENT_VIEWS.has(state.view)){pawAsleep=true;try{pawReact('idle-timeout')}catch(_){}}
  },90000);
  // [FASE-8] Di lingkungan uji Node/jsdom, timer 90 dtk ini menahan event loop
  // sehingga tes tidak pernah keluar. unref() tidak ada di browser — aman dicoba.
  if(pawIdleT&&typeof pawIdleT.unref==='function')pawIdleT.unref()
}
function pawIdlePoke(){
  const now=Date.now();
  if(pawAsleep){pawAsleep=false;try{pawReact('wake')}catch(_){}}
  if(now-pawIdleArmedAt<1000)return; // peredam: pointermove tidak menjadi metronom
  pawIdleArmedAt=now;pawIdleArm()
}
try{['pointerdown','pointermove','keydown','scroll','touchstart'].forEach(ev=>
  addEventListener(ev,pawIdlePoke,{passive:true,capture:true}))}catch(_){}
/* [FASE-4] 09 §3.1 APP_RETURN: kembali ke tab setelah lama pergi → sambutan; saat
   pergi, stempel kunjungan dimajukan supaya hitungan 4 jamnya jujur. */
try{document.addEventListener('visibilitychange',()=>{try{
  if(document.visibilityState==='hidden'){state.pawLastSeenAt=Date.now();save()}
  else{pawGreetReturn()}
}catch(_){}})}catch(_){}
// Wajah panel "Kata FIEZEL". Cadangannya ikon paw yang sama seperti sebelum m026-01:
// bentuk paw tetap satu sumber di features/ui/fiezel-icons.js lewat atribut data-fz-icon,
// berkas ini tidak menggambar path apa pun.
// Wajah panel "Kata FIEZEL". Mengembalikan SATU span coach-strip-face utuh, karena
// dua cabangnya butuh kelas wadah yang berbeda: maskot perlu has-mascot (latar krem +
// potong ke kepala, lihat fiezel-motion.css), ikon paw perlu fz-i seperti sebelumnya.
// Bentuk paw tetap satu sumber lewat data-fz-icon -> features/ui/fiezel-icons.js.
function pawFaceMarkup(){try{if(self.FiezelPaw?.ready?.())
  return '<span class="coach-strip-face has-mascot" aria-hidden="true"><fiezel-mascot class="coach-strip-mascot"></fiezel-mascot></span>'}catch(_){}
  return '<span class="coach-strip-face fz-i" data-fz-icon="paw" aria-hidden="true"></span>'}
// Streak yang putus hanya bisa dikenali dengan membandingkan dua kali cat Home;
// recomputeMeaningfulDays() sengaja TIDAK disentuh - ia lapisan data yang juga
// berjalan saat tidak ada layar yang tampil, dan reaksi gerak dari sana akan
// menyala di waktu yang salah. Ambangnya <=1 supaya hanya kejatuhan sungguhan
// (rantai hilang) yang memicunya, bukan koreksi angka biasa.
// [ADAPTASI] 14 §3.1 aturan 2: SFX karakter tidak boleh menimpa suara tutor yang sedang
// bicara. FiezelVoiceSay tidak mengekspor isSpeaking, jadi sinyalnya dirakit dari dua
// pengamat.
//
// m025-232: dulu baris keduanya membaca `speechSynthesis.speaking` milik cadangan peramban.
// Cadangan itu sudah dihapus, dan menggantinya dengan FiezelSpeechBridge.speaking() BUKAN
// sekadar tambal: jembatan itu mengikuti aliran event 'fiezel-speech' dari fasad, jadi ia
// menjawab benar untuk SEMUA lapisan yang tersisa - aset R2/ElevenLabs (L1), Cloudflare (C1),
// Puter (L2), dan neural di perangkat (L3). `speechSynthesis.speaking` dulu hanya tahu satu
// lapisan, yang paling bawah, sehingga SFX maskot tetap boleh menimpa suara L1 yang sedang
// berbunyi. Sinyal barunya lebih luas, bukan lebih sempit.
function voiceIsSpeaking(){
  try{if(self.FiezelSpeechBridge?.speaking?.())return true}catch(_){}
  try{if(self.FiezelPuterVoice?.status?.().speaking)return true}catch(_){}
  return false
}
let pawLastSeenStreak=null;
function pawStreakWatch(){const now=Number(state.streak)||0;
  // [ADAPTASI] OA-7 §4: paw_encourage menemani momen streak putus - vokalisasi "tidak
  // apa-apa", bukan bunyi kalah. Jatah 2×/sesi · jeda ≥20 dtk dijaga manifest (14 §3.2).
  if(pawLastSeenStreak!==null&&now<pawLastSeenStreak&&now<=1){pawReact('streak-lost');if(!voiceIsSpeaking())uiSfx('paw_encourage')}
  // [FASE-4] 09 §2.15: runtun hari 7/30/100 adalah milestone once-ever. Dibaca di
  // perbandingan dua cat Home yang sama — hanya KENAIKAN yang menyeberangi ambang.
  // Bunyinya streak_10 (20 §4: motif streak lengkap dengan mahkota), bukan fanfare baru.
  if(pawLastSeenStreak!==null&&now>pawLastSeenStreak&&[7,30,100].includes(now)){
    if(pawMilestone('streak-'+now))uiSfx('streak_10')
  }
  /* 2026-08-29 overhaul I14 (O3 §7 "Streak INCREASE"): rantai BERTAMBAH = selebrasi pendek
     (celebrating 1200ms, tanpa confetti — setState polos tidak menabur), hanya bila hari itu
     bukan milestone 7/30/100 (milestone sudah punya reaksinya lewat pawMilestone di atas).
     Dibaca di perbandingan dua cat Home yang sama dengan streak-lost; pawSetState = gerbang
     kurangi-gerak yang satu. Tidak pernah menyala di tengah pelajaran — home() satu-satunya
     pemanggil pawStreakWatch. */
  else if(pawLastSeenStreak!==null&&now>pawLastSeenStreak)pawSetState('celebrating',{hold:1200});
  pawLastSeenStreak=now}
// m025-84: sampai rilis ini go() tidak pernah menyentuh History API sama sekali, jadi
