function openFiezelAuthModal(initialTab){
  let currentTab=initialTab||'login';

  function renderAuthModalContent(){
    let tabContent='';
    const acc=self.FiezelAccount?.getAccount?.();

    if(currentTab==='login'){
      tabContent=`<div class="auth-form">
        <label class="auth-field-label">Handle Akun
          <input id="authLoginHandle" type="text" placeholder="Username / nama akun" maxlength="50" autocomplete="username">
        </label>
        <label class="auth-field-label">Kata Sandi
          <input id="authLoginPassword" type="password" placeholder="Masukkan kata sandi" autocomplete="current-password">
        </label>
        <div id="authModalError" class="auth-error-box" style="display:none"></div>
        <button type="button" id="btnAuthAction" class="primary" style="margin-top:6px">
          <i data-lucide="log-in"></i> Masuk
        </button>
      </div>`;
    } else if(currentTab==='register'){
      tabContent=`<div class="auth-form">
        <label class="auth-field-label">Handle Akun
          <input id="authRegHandle" type="text" placeholder="Username bebas (1–50 karakter)" maxlength="50" autocomplete="username">
        </label>
        <label class="auth-field-label">Kata Sandi
          <input id="authRegPassword" type="password" placeholder="Kata sandi bebas" autocomplete="new-password">
        </label>
        <label class="auth-field-label">Konfirmasi Kata Sandi
          <input id="authRegConfirm" type="password" placeholder="Ulangi kata sandi" autocomplete="new-password">
        </label>
        <div id="authModalError" class="auth-error-box" style="display:none"></div>
        <button type="button" id="btnAuthAction" class="primary" style="margin-top:6px">
          <i data-lucide="user-plus"></i> Daftar Akun Murid
        </button>
      </div>`;
    } else if(currentTab==='teacher'){
      tabContent=`<div class="auth-form">
        <label class="auth-field-label">Kode Undangan Guru
          <input id="authTeacherCode" type="text" placeholder="Kode 32 karakter (Crockford)" maxlength="32" style="text-transform:uppercase" autocomplete="off">
        </label>
        <p class="muted" style="font-size:0.85rem;margin-top:-2px">${FiezelI18n.t('guru.nama-otomatis')}</p>
        <div id="authModalError" class="auth-error-box" style="display:none"></div>
        <button type="button" id="btnAuthAction" class="primary" style="margin-top:6px">
          <i data-lucide="award"></i> Aktifkan & Buka Ruang Guru
        </button>
      </div>`;
    }

    const html=`<div class="modal-mark">FIEZEL AUTH</div>
      <h2>${FiezelI18n.t('account.card-title')}</h2>
      <div class="auth-tabs">
        <button type="button" class="auth-tab ${currentTab==='login'?'active':''}" data-tab="login">${FiezelI18n.t('account.tab-masuk')}</button>
        <button type="button" class="auth-tab ${currentTab==='register'?'active':''}" data-tab="register">${FiezelI18n.t('account.tab-daftar')}</button>
        <button type="button" class="auth-tab ${currentTab==='teacher'?'active':''}" data-tab="teacher">Guru</button>
      </div>
      <div id="authTabBody">${tabContent}</div>
      <div class="modal-actions" style="margin-top:16px">
        <button type="button" id="btnAuthCancel">${FiezelI18n.t('account.batal')}</button>
      </div>`;

    openModal(html);
    enhanceUI();

    $('btnAuthCancel').onclick=()=>{
      closeModal();
      setTimeout(openSettings,100);
    };

    document.querySelectorAll('.auth-tab').forEach(tabBtn=>{
      tabBtn.onclick=()=>{
        currentTab=tabBtn.getAttribute('data-tab');
        renderAuthModalContent();
      };
    });

    const actionBtn=$('btnAuthAction');
    const errBox=$('authModalError');

    if(actionBtn){
      actionBtn.onclick=async()=>{
        if(errBox)errBox.style.display='none';
        actionBtn.disabled=true;

        try{
          if(currentTab==='login'){
            const handle=$('authLoginHandle')?.value;
            const password=$('authLoginPassword')?.value;
            const res=await self.FiezelAccount?.login?.({handle,password});
            if(res?.ok){
              const h=res.account?.handle||self.FiezelAccount?.getAccount?.()?.handle||handle;
              showToast(`Berhasil masuk sebagai @${h}`);
              closeModal();
              setTimeout(openSettings,100);
              return;
            }
            if(errBox){
              errBox.textContent=res?.message||'Gagal masuk.';
              errBox.style.display='block';
            }
          } else if(currentTab==='register'){
            const handle=$('authRegHandle')?.value;
            const password=$('authRegPassword')?.value;
            const confirmPassword=$('authRegConfirm')?.value;
            const res=await self.FiezelAccount?.register?.({handle,password,confirmPassword});
            if(res?.ok){
              const h=res.account?.handle||self.FiezelAccount?.getAccount?.()?.handle||handle;
              showToast(FiezelI18n.t('account.toast-dibuat',{handle:h}));
              closeModal();
              setTimeout(openSettings,100);
              return;
            }
            if(errBox){
              errBox.textContent=res?.message||'Pendaftaran gagal.';
              errBox.style.display='block';
            }
          } else if(currentTab==='teacher'){
            const code=$('authTeacherCode')?.value;
            const res=await self.FiezelAccount?.activateTeacher?.({code});
            if(res?.ok){
              const tName=res.account?.teacherName||'Guru';
              showToast(FiezelI18n.t('guru.toast-akun-aktif',{nama:tName}));
              try{
                if(self.FiezelOnboarding?.markCompleted){
                  self.FiezelOnboarding.markCompleted(self,{at:Date.now(),via:'token',name:tName,role:'guru'});
                }
              }catch(_){}
              state.preferences={...state.preferences,role:'guru'};
              try{save()}catch(_){}
              closeModal();
              go('tutor');
              return;
            }
            if(errBox){
              errBox.textContent=res?.message||FiezelI18n.t('guru.aktivasi-gagal');
              errBox.style.display='block';
            }
          }
        }catch(_){
          if(errBox){
            errBox.textContent=FiezelI18n.t('account.err-umum');
            errBox.style.display='block';
          }
        }finally{
          actionBtn.disabled=false;
        }
      };
    }
  }

  renderAuthModalContent();
}
function neuralVoiceStatusMarkup(){const say=self.FiezelPuterVoice,online=say?.status?.()||{ready:false,sdkPresent:false,error:''};const runtime=self.FiezelVoiceRuntime,status=runtime?.status?.()||{prepared:false,ready:false,phase:'unavailable',totalBytes:0};const offline=self.FiezelVoiceOfflineAutoload?.status?.()||{done:false,armed:false};const label=online.ready?FiezelI18n.t('suara.siap'):FiezelI18n.t('suara.menyiapkan');
  // m025-121: kartu ini TIDAK menjual unduhan apa pun, dan itu keputusan yang sama dengan
  // m025-100. Cadangan perangkat menyiapkan dirinya sendiri di latar; yang ditampilkan di
  // sini hanyalah kenyataan sesudahnya, satu baris, tanpa tombol dan tanpa angka megabita.
  const backupLine=offline.done?FiezelI18n.t('suara.cadangan'):'';
  return `<article class="voice-setup-card"><div class="voice-setup-copy"><h2>${esc(label)}</h2><p id="neuralVoiceProgress">${FiezelI18n.t('suara.ket-subtitle')}</p>${online.error?`<p class="muted">${FiezelI18n.t('suara.status-error',{galat:esc(online.error)})}</p>`:''}<label class="neural-voice-choice" for="neuralRateInput"><span>${FiezelI18n.t('suara.kecepatan-bicara')}</span><input id="neuralRateInput" type="range" min="${NEURAL_RATE_MIN}" max="${NEURAL_RATE_MAX}" step="${NEURAL_RATE_STEP}" value="${selectedNeuralRate()}"><small id="neuralRateValue">${esc(neuralRateLabel(selectedNeuralRate()))}</small></label>${backupLine?`<p class="muted">${esc(backupLine)}</p>`:''}</div><div class="voice-setup-actions"><button id="testNeuralVoice" type="button"><i data-lucide="volume-2"></i> ${FiezelI18n.t('suara.tes')}</button></div></article>`}
// m025-96: menguji mesin yang benar-benar dipakai murid. Menguji mesin lokal di sini
// akan melaporkan 'suara siap' padahal jalur yang dipakai pelajaran adalah yang lain.
async function testNeuralVoice(){const button=$('testNeuralVoice'),say=self.FiezelVoiceSay;if(!button||!say?.say)return;button.disabled=true;const hint=$('neuralVoiceProgress');try{const ok=await say.say(`Hello ${learnerName()}. This is your FIEZEL voice.`,{speed:selectedNeuralRate()});if(hint)hint.textContent=ok?FiezelI18n.t('suara.tes-selesai'):FiezelI18n.t('suara.tak-berbunyi');showToast(ok?FiezelI18n.t('suara.terdengar'):FiezelI18n.t('suara.belum-berbunyi'))}catch(error){if(hint)hint.textContent=FiezelI18n.t('suara.tes-gagal-detail',{galat:String(error?.message||error)});showToast(FiezelI18n.t('suara.tes-gagal'))}finally{button.disabled=false;enhanceUI()}}

/* =====================================================================================
   V6 SISI PEMANGGIL - menghangatkan kalimat BERIKUTNYA (reports/voice-v6-callers.md)

   Tiga perbaikan lapisan bawah sudah ter-merge dan terukur:
     - FiezelVoiceSay.prefetch() benar-benar sampai ke mesin neural lokal
       (V5, metrik JEDA TERDENGAR: 4.510,7 -> 797,2 ms; reports/voice-v5-prefetch.md §2,
       harness-door.html + measure_door.py. Itu angka pekerjaan V5, BUKAN angka
       pekerjaan sisi-pemanggil di bawah - dua metrik berbeda, jangan dirangkai),
     - prosody/service.planUtterance() menerima TEKS UTUH,
     - pemutar memangkas keheningan dan menyambung antrean lintas panggilan
       (reports/voice-v2-player.md).

   ANGKA UNTUK PEKERJAAN DI BAWAH INI, dan mana yang berlaku untuk produksi
   (pelabelan diperbaiki setelah reports/add-a10-kepatuhan.md KB-6; nol angka dihapus):
     - metrik V6 adalah JEDA PENJADWALAN (meanSchedulingGapMs), bukan jeda terdengar.
     - pola SATU KALIMAT per panggilan (classroom, tutor, flashcards, kuis):
       3.750,6 -> 449,1 ms, porsi sunyi 47,69% -> 9,69%
       (reports/voice-v6-callers.md §4, voice-v6-data/caller-measurements.json).
     - pola NARASI LIBRARY yang benar-benar dikirim - blok bertangga
       (LEAD_BLOCK_CHARS 80, RAMP_COVER_FACTOR 1,15) - membayar lebih dan itulah
       angka produksi untuk Library: jeda penjadwalan 560,6 ms, jeda terdengar
       1.286,0 ms, porsi sunyi 12,6%, suara pertama 2.816,8 ms
       (reports/voice-v6-callers.md §5, voice-v6-data/block-measurements.json).
     Jadi "449 ms" TIDAK boleh dikutip sebagai angka Library, dan "4.510 -> 797"
     TIDAK boleh dirangkai dengan "3.750 -> 449" sebagai satu tren.

   Ketiga perbaikan lapisan bawah itu tidak berbuah selama PEMANGGIL mengirim satu
   kalimat lalu menunggu bunyi habis sebelum kalimat berikutnya digenerasi. Dua fungsi
   di bawah ini adalah bentuk tunggal dari "hangatkan yang berikutnya" untuk seluruh app.js.

   EMPAT PAGAR, dan semuanya sengaja:
     1. TIDAK memicu unduhan model. Di sini TIDAK ADA prepare()/ensureReady()/prewarm().
        Kontrak v5 sudah menjamin prefetch menjawab false dengan tenang selama aset
        belum prepared, dan itu memang jawaban yang benar untuk murid baru.
     2. Ditunda satu task (idle bila peramban punya requestIdleCallback). Mengajukan N+1
        di giliran JS yang sama dengan say(N) membuat N+1 memesan mesin single-flight
        lebih dulu - inversi antrean m025-47, pola yang sama dengan warmNext() Library.
     3. Menghormati penghenti. Setiap pengajuan mencatat voicePrefetchGeneration; stop,
        pindah layar, atau tab disembunyikan menaikkan angka itu, dan pengajuan yang
        menganggur batal SEBELUM menyentuh pintu suara. Prefetch sendiri tidak pernah
        berbunyi, jadi ini menjaga hal kedua: CPU tidak dipakai untuk kalimat yang sudah
        tidak akan didengar siapa pun.
     4. Senyap. Tidak ada toast, tidak ada subtitle, tidak ada galat yang menjalar.
   ===================================================================================== */
let voicePrefetchGeneration=0;
function cancelVoicePrefetch(){voicePrefetchGeneration++;return voicePrefetchGeneration}
function prefetchNextVoice(next,options){
  const say=self.FiezelVoiceSay;
  const english=String((typeof next==='string'?next:next&&next.en)||'').trim();
  if(!english)return false;
  if(!say||typeof say.prefetch!=='function')return false;
  const generation=voicePrefetchGeneration,opts={...(options||{})};
  const run=()=>{if(generation!==voicePrefetchGeneration)return;try{say.prefetch(english,opts)}catch{}};
  if(typeof requestIdleCallback==='function')requestIdleCallback(run,{timeout:1200});
  else setTimeout(run,0);
  return true;
}
// m025-33 FIEZEL Classroom: Category -> Topic -> Classroom. Fiezel speaks English with
// the mandatory neural engine; the Indonesian line is authored subtitle text, so the
// lesson works fully even when the optional Indonesian bundle is not downloaded.
let classroomSession=null,classroomPack=null,classroomSessionLevel='',classroomSpeaking=false;
/**
 * m025-117: bank materi menyimpan token {name}, bukan nama sungguhan - aturan yang sama
 * dengan seluruh naskah aplikasi (lihat personalize() di kepala berkas). Penggantian
 * dilakukan SEKALI saat paket dimuat, bukan di setiap titik render: paketnya di-cache,
 * jadi satu penelusuran murah dan tidak ada satu pun titik render yang bisa lupa.
 */
function personalizeContent(value){
  if(typeof value==='string')return personalize(value);
  if(Array.isArray(value))return value.map(personalizeContent);
  if(value&&typeof value==='object'){const out={};for(const [k,v] of Object.entries(value))out[k]=personalizeContent(v);return out}
  return value
}
async function loadClassroomPack(){if(classroomPack)return classroomPack;const r=await fetch('./features/classroom/classroom-lessons-v1.json',{credentials:'same-origin'});if(!r.ok)throw new Error('classroom_pack_unavailable');classroomPack=personalizeContent(await r.json());return classroomPack}
function classroomSubtitle(text){const el=$('classroomSubtitle');if(el)el.textContent=text||''}
// m025-96: Classroom sudah punya pasangan {en,id} sendiri, jadi barisnya dipakai
// langsung dan tidak menghabiskan jatah terjemahan. Subtitle bawaan Classroom tetap
// dipertahankan karena ia hidup di dalam kartu pelajaran, bukan di pita bawah layar.
// V6: `next` adalah teks Inggris yang akan dibacakan SESUDAH baris ini. Bila pemanggil
// tidak menyebutkannya, urutan segmen Classroom deterministik, jadi kursor sesi diintip
// lewat peekSegment() - accessor yang TIDAK memindahkan kursor (nextSegment() memindahkan,
// dan itulah kenapa ia tidak bisa dipakai untuk mengintip).
function classroomPeekNextText(){try{const seg=classroomSession&&classroomSession.peekSegment?classroomSession.peekSegment():null;return seg?seg.en:''}catch{return ''}}
async function classroomSpeak(en,id,next){classroomSubtitle(id);const say=self.FiezelVoiceSay;if(!say?.say)return;if(classroomSpeaking)return;classroomSpeaking=true;try{const speed=selectedNeuralRate();const speaking=say.say({en,id},{speed});
  // Diajukan SESUDAH say() berangkat, bukan sebelum: yang dihangatkan adalah kalimat
  // berikutnya, dan yang harus lebih dulu memesan mesin adalah kalimat yang sedang didengar.
  prefetchNextVoice(next===undefined?classroomPeekNextText():next,{speed});
  await speaking}catch(e){const el=$('classroomVoiceNote');if(el)el.textContent=FiezelI18n.t('kelas.suara-belum-siap',{galat:String(e?.message||e)})}finally{classroomSpeaking=false}}
// Tumpukan tutor/Classroom (81 KB) juga dimuat malas. Pembungkus ini yang menjembatani
// dua kenyataan: ./features/tutor-classroom/fiezel-tutor-v3.js MENGGANTI global
// `classroom` dengan renderernya sendiri saat ia dieksekusi, dan sekarang ia bisa saja
// belum dieksekusi ketika murid menekan tabnya. Identitas fungsi asli ditangkap di
// classroomBaseRenderer supaya penyerahan ke renderer tutor tidak pernah berubah menjadi
// rekursi tak terbatas ke diri sendiri.
async function classroom(){
  setApp('<section class="fade classroom-page"><div class="card">'+FiezelI18n.t('kelas.memuat')+'</div></section>');
  try{await self.FiezelLazy?.load?.('classroom')}catch{}
  const current=self.classroom;
  /* D6 P1-1: pembanding rekursi harus PEMBUNGKUS ini sendiri (classroom), bukan hanya
     classroomBaseRenderer. Bila lazy-load tutor-v3 gagal, global `classroom` tidak pernah
     diganti dan `current` adalah pembungkus ini - memanggilnya lagi = rekursi async tak
     berujung ("Memuat Classroom…" selamanya). Jalur gagal kini jatuh ke renderer bawaan. */
  /* Class-hub: pembanding memakai referensi pembungkus yang DITANGKAP (tutorClassroomWrapper),
     karena setelah tutor-v3 memuat, identifier global `classroom` sudah menunjuk ke penimpanya. */
  if(typeof current==='function'&&current!==tutorClassroomWrapper&&current!==classroomBaseRenderer)return current();
  return classroomBaseRenderer()
}
/* Tab "Kelas" di bottom nav = Class hub (Guru ↔ Murid ↔ Braincore). Pelajaran tutor bersuara
   (classroom() di atas) tetap hidup sebagai kartu "Tutor FIEZEL" di dalam hub - tidak dibuang. */
const tutorClassroomWrapper=classroom;
function classHubView(){
  const hub=self.FiezelClassHub;
  if(!hub){setApp('<section class="fade classroom-page"><div class="card">'+FiezelI18n.t('kelas.memuat')+'</div></section>');return}
  setApp('<div id="fzClassHub" class="fade"></div>');
  const host=$('fzClassHub');if(!host)return;
  hub.mountStudent(host,{go,toast:showToast,afterRender:()=>{try{refreshIcons()}catch{}},openTutor:()=>tutorClassroomWrapper()});
}
self.classHubView=classHubView;
/* D6 P1-1 (bug wiring terbesar): dulu baris ini menangkap `classroom` - PEMBUNGKUSNYA
   SENDIRI - sehingga classroomBase (renderer Classroom bawaan lengkap, ±90 baris) tidak
   pernah bisa dipanggil, dan fallback saat lazy-load gagal berubah menjadi rekursi.
   Yang benar: tangkap renderer ASLI classroomBase (deklarasi fungsi ter-hoist, jadi
   referensi ini sah walau deklarasinya di bawah). */
const classroomBaseRenderer=classroomBase;
async function classroomBase(){
  let pack;try{pack=await loadClassroomPack()}catch(e){setApp(`<section class="fade classroom-page"><div class="card"><b>${FiezelI18n.t('kelas.gagal-muat')}</b><p class="muted">${esc(e?.message||e)}</p></div></section>`);return}
  if(!self.FiezelClassroom){setApp('<section class="fade classroom-page"><div class="card"><b>'+FiezelI18n.t('kelas.runtime-hilang')+'</b></div></section>');return}
  const level=getActiveLevel();
  if(!classroomSession||classroomSessionLevel!==level){classroomSession=self.FiezelClassroom.createSession(pack,{getActiveLevel});classroomSessionLevel=level}
  renderClassroom();
}
function renderClassroom(){
  const s=classroomSession,snap=s.snapshot();
  let body='';
  if(snap.phase==='category'){
    body=`<div class="classroom-grid">${s.categories().map(c=>`<button class="classroom-cat" data-cat="${esc(c.id)}"><i data-lucide="${esc(c.icon)}"></i><b>${esc(c.label)}</b><small>${esc(c.hint)}</small></button>`).join('')}</div>`;
  }else if(snap.phase==='topic'){
    const list=s.lessonsIn(snap.categoryId);
    body=list.length?`<div class="classroom-grid">${list.map(l=>`<button class="classroom-cat" data-lesson="${esc(l.id)}"><b>${esc(l.topic)}</b><small>${esc(l.level)}</small></button>`).join('')}</div>`:'<div class="card">'+FiezelI18n.t('kelas.topik-kosong')+'</div>';
    body+='<div class="classroom-actions"><button data-back="category">'+FiezelI18n.t('umum.kembali')+'</button></div>';
  }else if(snap.phase==='teach'){
    const seg=s.currentSegment();
    body=`<article class="classroom-board"><h2>${esc(snap.board.title)}</h2><p class="classroom-formula">${esc(snap.board.formula)}</p><ul>${snap.board.examples.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></article>
    <article class="classroom-subtitle-card"><p class="classroom-en">${esc(seg?seg.en:'')}</p><p id="classroomSubtitle" class="classroom-id">${esc(seg?seg.id:'')}</p><p id="classroomVoiceNote" class="muted"></p></article>
    <div class="classroom-actions"><button data-replay="1"><i data-lucide="volume-2"></i> ${FiezelI18n.t('kelas.replay-audio')}</button><button class="primary" data-next="1">${FiezelI18n.t(snap.segmentIndex<snap.segmentCount-1?'kelas.next':'kelas.start-practice')} <i data-lucide="arrow-right"></i></button></div>
    <p class="muted">${FiezelI18n.t('kelas.bagian',{idx:snap.segmentIndex+1,total:snap.segmentCount})}</p>`;
  }else if(snap.phase==='quiz'){
    const q=s.currentQuestion();
    body=`<article class="classroom-board"><h2>${esc(q.prompt)}</h2></article>
    <div class="classroom-options">${q.options.map((o,i)=>`<button class="classroom-option" data-opt="${i}">${esc(o)}</button>`).join('')}</div>
    <article class="classroom-subtitle-card"><p class="classroom-en" id="classroomFeedbackEn"></p><p id="classroomSubtitle" class="classroom-id"></p><p id="classroomVoiceNote" class="muted"></p></article>
    <p class="muted">${FiezelI18n.t('kelas.q-index',{idx:snap.questionIndex+1,total:snap.questionCount})}${snap.remediating?FiezelI18n.t('kelas.remediasi'):''}</p>`;
  }else{
    body=`<article class="classroom-board"><h2>${FiezelI18n.t('kelas.skor',{persen:snap.scorePercent})}</h2><p>${FiezelI18n.t('kelas.skor-rinci',{right:snap.correct,total:snap.questionCount})}</p></article>
    <div class="classroom-actions"><button class="primary" data-restart="1">${FiezelI18n.t('kelas.topik-lain')}</button></div>`;
  }
  setApp(`<section class="fade classroom-page"><div class="section-head"><div><h1>${FiezelI18n.t('kelas.judul')}</h1><p>${FiezelI18n.t('kelas.sub-judul',{level:esc(getActiveLevel())})}</p></div>${levelControlMarkup()}</div>${body}</section>`);
  wireClassroom();
}
function wireClassroom(){
  const s=classroomSession;
  // m025-117: Classroom adalah "folder" yang sesungguhnya - kategori, lalu topik, lalu
  // pelajaran, semuanya di dalam SATU view. Setiap turun satu tingkat mendaftarkan stage
  // yang tahu cara naik kembali tepat satu tingkat, bukan keluar dari seluruh Classroom.
  document.querySelectorAll('[data-cat]').forEach(b=>b.addEventListener('click',()=>{const cat=b.dataset.cat;s.chooseCategory(cat);enterStage('classroom-topic',()=>{s.reset();s.chooseCategory(cat);renderClassroom()});renderClassroom()}));
  document.querySelectorAll('[data-lesson]').forEach(b=>b.addEventListener('click',()=>{const cat=s.snapshot().categoryId,lesson=b.dataset.lesson;s.chooseLesson(lesson);enterStage('classroom-lesson',()=>{s.reset();if(cat)s.chooseCategory(cat);s.chooseLesson(lesson);renderClassroom()});renderClassroom();const seg=s.currentSegment();if(seg)classroomSpeak(seg.en,seg.id)}));
  // Keluar dari pelajaran adalah penghenti: pengajuan prefetch yang masih menganggur
  // dibatalkan di sini supaya CPU tidak menggenerasi kalimat yang tidak akan didengar.
  document.querySelector('[data-back="category"]')?.addEventListener('click',()=>{cancelVoicePrefetch();exitStage()});
  document.querySelector('[data-replay]')?.addEventListener('click',()=>{const seg=s.currentSegment();if(seg)classroomSpeak(seg.en,seg.id)});
  document.querySelector('[data-next]')?.addEventListener('click',()=>{s.nextSegment();renderClassroom();const seg=s.currentSegment();if(seg)classroomSpeak(seg.en,seg.id)});
  document.querySelector('[data-restart]')?.addEventListener('click',()=>{cancelVoicePrefetch();leaveAllStages();s.reset();renderClassroom()});
  document.querySelectorAll('[data-opt]').forEach(b=>b.addEventListener('click',()=>{
    const {result}=s.answer(Number(b.dataset.opt));
    const en=$('classroomFeedbackEn');if(en)en.textContent=result.feedback.en;
    classroomSubtitle(result.feedback.id);
    // Feedback kuis: TIDAK ada "kalimat berikutnya" yang bisa diketahui - kalimat sesudah
    // ini lahir dari jawaban murid berikutnya, jadi next dikirim kosong DENGAN SENGAJA
    // (menghangatkan tebakan berarti membakar CPU untuk teks yang mungkin tidak terpakai).
    classroomSpeak(result.feedback.en,result.feedback.id,'');
    b.classList.add(result.correct?'is-correct':'is-wrong');
    document.querySelectorAll('[data-opt]').forEach(x=>{x.disabled=true});
    setTimeout(()=>{renderClassroom();if(s.snapshot().phase==='quiz'&&!s.snapshot().remediating){}},1400);
  }));
  enhanceUI();
}
// m025-115: satu mesin, tiga pintu. Skills Lab tetap utuh sebagai hub Speaking+Listening,
