// m025-84: dipasang di ujung berkas, saat go()/state/VALID_VIEWS sudah ada, dan SEBELUM
// load() supaya navigasi pertama pun sudah terekam di riwayat.
function installBackNav(){
  try{
    return self.FiezelBackNav?.install?.(self,{
      currentView:()=>state.view,
      knownView:v=>VALID_VIEWS.has(v),
      homeView:'home',
      // Perpindahan view dikembalikan ke go() supaya kembali memakai transisi, bunyi, dan
      // aturan kurangi-gerak yang persis sama dengan maju - hanya tanpa entri baru.
      applyView:v=>go(v,{viaHistory:true}),
      // Selama sebuah lapisan penuh layar menutupi aplikasi - undangan notifikasi, gerbang
      // akun Puter, splash, atau perkenalan - tidak ada tekanan kembali yang boleh mengubah
      // apa pun di belakangnya.
      //
      // Dulu baris pertama membaca kelas 'notification-locked' di <body>. Kelas itu tidak
      // pernah dipasang lagi sejak notifikasi berhenti menjadi syarat masuk, jadi ia
      // diganti dengan pertanyaan yang sebenarnya: apakah panelnya sedang di layar. Panel
      // undangan memang tidak mengunci aplikasi, tetapi selama ia terbuka ia tetap dialog -
      // tombol kembali harus menutupnya, bukan menavigasi di belakangnya.
      // m025-254: baris `daily-locked` di sini ikut hilang bersama kunci target harian.
      // Kelas itu dipasang oleh satu-satunya modul yang pernah menuliskannya, dan modul
      // itu sudah tidak ada - memeriksanya hanya akan membuat pembaca berikutnya mencari
      // gerbang yang tidak pernah menyala.
      locked:()=>{
        try{
          const welcome=document.getElementById?.('welcome');
          if(welcome&&!welcome.classList.contains('hidden'))return true;
          if(document.body?.classList?.contains?.('auth-locked'))return true;
          return !!document.querySelector?.('.fiezel-splash,.fiezel-ob');
        }catch{return false}
      },
      // m025-237: tekanan kembali yang menghabiskan tumpukan tidak langsung menutup PWA -
      // ia melepas entri penanda dan menyerahkan keputusan ke tekanan BERIKUTNYA. Tanpa
      // sepatah kata pun, jeda itu terbaca sebagai tekanan yang tidak melakukan apa-apa;
      // dengan kalimat ini ia terbaca sebagai jaring pengaman, dan gestur tepi yang meleset
      // di beranda tidak lagi bisa membuang sesi belajar murid.
      onExit:()=>{try{showToast(FiezelI18n.t('nav.tekan-lagi-untuk-keluar'))}catch(_){}}
    })||null
  }catch{return null}
}
bindUiSfxDelegation();
installBackNav();
// Audit splash-SFX 2026-08-28: konteks audio + dekode splash_intro disiapkan SEBELUM
// load() mengunduh ~2,7 MB JSON. Di lingkungan yang mengizinkan autoplay (PWA terpasang
// Android/desktop, MEI tinggi) konteks yang dibuat di sini lahir 'running', sehingga nada
// pembuka bisa berbunyi TANPA GESTUR saat splash tampil. Di lingkungan terblokir hanya
// dekodenya yang berjalan - izin dan persiapan adalah dua hal terpisah, dan tidak ada
// satu nada pun yang dijadwalkan dari sini (m025-84 utuh). Preferensi feedbackSounds
// sudah terbaca: __getFiezelState terpasang beberapa baris di atas.
try{self.FiezelUiSfx?.prepare?.('splash_intro',self)}catch(_){}
// m025-84: boot yang gagal harus MENYINGKIRKAN splash frame-pertama sebelum menulis pesan
// galat - kalau tidak, pesannya ditulis ke #app yang tertutup penuh oleh splash dan murid
// hanya melihat layar sambutan yang menggantung selamanya.
/* W1 P0-1 (16-002): kartu galat boot berbahasa murid, bukan berbahasa fetch. Pesannya
   bercabang menurut penyebab yang bisa diperiksa (offline / file:// / server-jaringan),
   isi galat mentah ("Failed to fetch") dibuang ke console.debug, dan ada tombol "Coba lagi"
   yang menjalankan ulang load() tanpa memaksa murid me-reload halaman sendiri. */
// m026 GEO-IP: deteksi negara berbasis IP untuk murid BARU. Kontrak owner: pengunjung dari
// Thailand yang belum pernah memilih bahasa manual → antarmuka otomatis Thai; selain itu tetap
// 'id'. Pilihan MANUAL (onboarding/Pengaturan) selalu menang — sekali learnerLocaleExplicit
// true, fungsi ini langsung mundur. Fetch dijaga timeout pendek + fail-soft: offline, jaringan
// lambat, atau layanan mati TIDAK PERNAH memblokir boot PWA (jatuh ke 'id'). Dicek sekali per
// perangkat (localeAutoDetected) supaya tidak fetch tiap buka; kegagalan tidak menandai selesai
// supaya bisa dicoba lagi kunjungan berikutnya.
function fetchCountryCode(timeoutMs){
  if(typeof fetch!=='function')return Promise.resolve(null);
  var ctrl=typeof AbortController!=='undefined'?new AbortController():null;
  var timer=setTimeout(function(){try{ctrl&&ctrl.abort()}catch(_){}},timeoutMs);
  return fetch('https://ipwho.is/?fields=success,country_code',ctrl?{signal:ctrl.signal}:{})
    .then(function(res){return res&&res.ok?res.json():null})
    .then(function(data){
      if(data&&data.success!==false&&typeof data.country_code==='string')return data.country_code.toUpperCase();
      return null;
    })
    .catch(function(){return null})
    .then(function(cc){clearTimeout(timer);return cc});
}
function maybeAutoDetectLocale(){
  try{
    var prefs=state&&state.preferences||{};
    if(prefs.learnerLocaleExplicit===true)return Promise.resolve();
    if(prefs.localeAutoDetected===true)return Promise.resolve();
  }catch(_){return Promise.resolve()}
  return fetchCountryCode(2000).then(function(cc){
    if(cc===null)return; // gagal/timeout → jangan tandai, coba lagi nanti; tetap 'id'
    var next={...state.preferences,localeAutoDetected:true};
    if(cc==='TH')next.learnerLocale='th';
    state.preferences=next;state.coachCache=null;
    try{save()}catch(_){}
    if(cc==='TH'){try{self.FiezelI18n?.setLocale?.('th')}catch(_){}}
  }).catch(function(){});
}
function bootFiezel(){try{self.FiezelAccount?.getMe?.();}catch(_){}return maybeAutoDetectLocale().then(function(){return load()}).catch(e=>{dismissBootSplash();
  try{console.debug('FIEZEL boot error:',e)}catch(_){}
  const offline=typeof navigator!=='undefined'&&navigator.onLine===false,fileProto=typeof location!=='undefined'&&location.protocol==='file:';
  const msg=offline?FiezelI18n.t('boot.offline-msg')
   :fileProto?FiezelI18n.t('boot.file-protocol-msg')
   :FiezelI18n.t('boot.load-failed-msg');
  setApp(`<div class="error"><p>${esc(msg)}</p><div class="modal-actions"><button type="button" id="bootRetry" class="primary">${FiezelI18n.t('boot.retry-btn')}</button></div></div>`);
  const btn=$('bootRetry');
  if(btn)btn.onclick=()=>{btn.disabled=true;btn.setAttribute('aria-busy','true');btn.textContent=FiezelI18n.t('boot.loading');bootFiezel()};
})}
bootFiezel();
